<template>
  <div
    v-if="loading"
    class="loading-screen"
  >
    <h2>{{ $t("common.loading") }}</h2>
  </div>

  <LoginModal
    v-else-if="!session.firebaseUser"
    :is-visible="true"
    @login-success="onLoginSuccess"
  />

  <div
    v-else-if="
      session.initialized &&
      session.profile?.active === false
    "
    class="inactive-account-page"
  >
    <div class="inactive-account-card">
      <h1>
        {{
          $t(
            "accountInactive.title",
          )
        }}
      </h1>

      <p>
        {{
          $t(
            "accountInactive.message",
          )
        }}
      </p>

      <p>
        {{
          $t(
            "accountInactive.contactAdmin",
          )
        }}
      </p>

      <button
        type="button"
        @click="handleSignOut"
      >
        {{
          $t(
            "accountInactive.signOut",
          )
        }}
      </button>
    </div>
  </div>

  <NoSchoolPage
    v-else-if="
      session.initialized &&
      !isSystemAdmin &&
      session.schools.length === 0
    "
    :user="session.firebaseUser"
    :profile="session.profile"
    @sign-out="handleSignOut"
  />

  <div
    v-else
    class="layout"
  >
    <NavigationMenu
      :current-page="navigationPage"
      :user="session.firebaseUser"
      :profile="session.profile"
      :schools="session.schools"
      :active-school="session.activeSchool"
      :is-system-admin="isSystemAdmin"
      :effective-role="effectiveRole"
      :can-access-admin="canAccessAdmin"
      :can-access-students="canAccessStudents"
      :can-access-classes="canAccessClasses"
      :can-manage-school-structure="
        canManageSchoolStructure
      "
      @change-page="changePage"
      @change-school="handleSchoolChange"
      @open-profile="openProfile"
      @sign-out="handleSignOut"
    />

    <main>
      <DashboardPage
        v-if="currentPage === 'dashboard'"
        :school-id="session.activeSchool"
        :actor-role="
          isSystemAdmin
            ? 'system-admin'
            : session.membership?.role || ''
        "
        :actor-uid="
          session.firebaseUser?.uid || ''
        "
      />

      <StudentManager
        v-if="
          currentPage === 'students' &&
          canAccessStudents
        "
        :school-id="session.activeSchool"
        :actor-role="
          isSystemAdmin
            ? 'system-admin'
            : session.membership?.role || ''
        "
      />

      <CourseManager
        v-if="
          currentPage === 'courses' &&
          canManageSchoolStructure
        "
        :school-id="session.activeSchool"
      />

      <BuildingManager
        v-if="
          currentPage === 'buildings' &&
          canManageSchoolStructure
        "
        :school-id="session.activeSchool"
      />

      <RoomManager
        v-if="
          currentPage === 'rooms' &&
          canManageSchoolStructure
        "
        :school-id="session.activeSchool"
      />

      <RoomReservationManager
        v-if="
          currentPage === 'reservations' &&
          canManageSchoolStructure
        "
        :school-id="session.activeSchool"
      />

      <ClassManager
        v-if="
          currentPage === 'classes' &&
          canAccessClasses
        "
        :actor-role="
          isSystemAdmin
            ? 'system-admin'
            : session.membership?.role || ''
        "
        :actor-uid="
          session.firebaseUser?.uid || ''
        "
        :school-id="session.activeSchool"
        @manage-class="openClassWorkspace"
      />

      <ClassWorkspace
        v-if="
          currentPage === 'class-workspace' &&
          canAccessClasses
        "
        :school-id="session.activeSchool"
        :class-id="selectedClassId"
        :actor-role="
          isSystemAdmin
            ? 'system-admin'
            : session.membership?.role || ''
        "
        :actor-uid="
          session.firebaseUser?.uid || ''
        "
        @back="closeClassWorkspace"
      />

      <SettingsPage
        v-if="currentPage === 'settings'"
      />

      <ProfilePage
        v-if="currentPage === 'profile'"
        :user="session.firebaseUser"
        :profile="session.profile"
        @profile-updated="handleProfileUpdated"
      />

      <AdminPage
        v-if="
          currentPage === 'admin' &&
          canAccessAdmin
        "
        :school-id="session.activeSchool"
        :is-system-admin="isSystemAdmin"
        :is-school-admin="isSchoolAdmin"
        :current-user-uid="
          session.firebaseUser?.uid || ''
        "
      />
    </main>
  </div>
</template>

<script>
import {
  onAuthStateChanged,
  signOut,
} from "firebase/auth";

import {
  auth,
} from "./firebase-init";

import {
  getCurrentUserProfile,
  updateActiveSchool,
} from "./services/userService";
import {
  getUserSchools,
  watchSchools,
} from "./services/schoolService";
import {
  getSchoolMembership,
  getUserSchoolMemberships,
} from "./services/membershipService";

import NavigationMenu from "./components/NavigationMenu.vue";
import LoginModal from "./components/LoginModal.vue";

import DashboardPage from "./pages/DashboardPage.vue";

import NoSchoolPage from "./pages/NoSchoolPage.vue";
import SettingsPage from "./pages/SettingsPage.vue";
import ProfilePage from "./pages/ProfilePage.vue";

import {defineAsyncComponent} from "vue";

const StudentManager = defineAsyncComponent(() =>
  import("./pages/StudentManager.vue"));

const CourseManager = defineAsyncComponent(() =>
  import("./pages/CourseManager.vue"));

const BuildingManager = defineAsyncComponent(() =>
  import("./pages/BuildingManager.vue"));

const RoomManager = defineAsyncComponent(() =>
  import("./pages/RoomManager.vue"));

const RoomReservationManager = defineAsyncComponent(() =>
  import("./pages/RoomReservationManager.vue"));

const ClassManager = defineAsyncComponent(() =>
  import("./pages/ClassManager.vue"));

const ClassWorkspace = defineAsyncComponent(() =>
  import("./pages/ClassWorkspace.vue"));

const AdminPage = defineAsyncComponent(() =>
  import("./pages/AdminPage.vue"));


export default {
  name: "App",

  components: {
    NavigationMenu,
    LoginModal,
    NoSchoolPage,
    DashboardPage,
    StudentManager,
    CourseManager,
    BuildingManager,
    RoomManager,
    RoomReservationManager,
    ClassManager,
    ClassWorkspace,
    SettingsPage,
    ProfilePage,
    AdminPage,
  },

  data() {
    return {
      loading: true,
      currentPage: "dashboard",
      selectedClassId: "",
      schoolUnsubscribe: null,

      session: {
        firebaseUser: null,
        profile: null,
        schools: [],
        activeSchool: null,
        membership: null,
        initialized: false,
      },
    };
  },

  computed: {
    navigationPage() {
      if (this.currentPage === "class-workspace") {
        return "classes";
      }

      return this.currentPage;
    },

    isSystemAdmin() {
      const result =
        this.session.profile?.active !== false &&
        this.session.profile?.systemRole ===
          "system-admin";

      return result;
    },

    isSchoolAdmin() {
      return (
        this.session.profile?.active !== false &&
        this.session.membership?.active !== false &&
        this.session.membership?.role ===
          "school-admin"
      );
    },

    effectiveRole() {
      if (this.isSystemAdmin) {
        return "system-admin";
      }

      if (
        this.session.membership?.active === false
      ) {
        return "";
      }

      return (
        this.session.membership?.role ||
        ""
      );
    },

    canAccessAdmin() {
      return (
        this.isSystemAdmin ||
        this.isSchoolAdmin
      );
    },

    canAccessStudents() {
      return (
        this.isSystemAdmin ||
        this.isSchoolAdmin ||
        this.session.membership?.role === "teacher"
      );
    },

    canAccessClasses() {
      return (
        this.isSystemAdmin ||
        this.isSchoolAdmin ||
        this.session.membership?.role === "teacher"
      );
    },

    canManageSchoolStructure() {
      return (
        this.isSystemAdmin ||
        this.isSchoolAdmin
      );
    },
  },

  beforeUnmount() {
    if (this.schoolUnsubscribe) {
      this.schoolUnsubscribe();
    }
  },
  mounted() {
    onAuthStateChanged(auth, async (user) => {
      this.loading = false;

      if (!user) {
        this.session.firebaseUser = null;
        return;
      }

      await this.initializeSession(user);
    });
  },

  methods: {
    async initializeSession(firebaseUser) {
      try {
        const profile =
          await getCurrentUserProfile(
            firebaseUser.uid,
          );

        if (
          profile?.active === false
        ) {
          this.session.firebaseUser =
            firebaseUser;

          this.session.profile =
            profile;

          this.session.schools = [];
          this.session.activeSchool = null;
          this.session.membership = null;
          this.session.initialized = true;

          return;
        }

        const isSystemAdmin =
          profile?.systemRole ===
          "system-admin";

        let schools = [];
        let memberships = [];

        if (isSystemAdmin) {
          schools =
            await getUserSchools(
              profile?.schools || [],
            );
        } else {
          memberships =
            await getUserSchoolMemberships(
              firebaseUser.uid,
            );

          const schoolIds =
            memberships
              .map(
                (membership) =>
                  membership.schoolId,
              )
              .filter(Boolean);
          
          schools =
            await getUserSchools(
              schoolIds,
            );
        }

        let activeSchool =
          profile?.activeSchool || null;

        const activeSchoolExists =
          schools.some(
            (school) =>
              school.id === activeSchool,
          );

        if (!activeSchoolExists) {
          activeSchool =
            schools.length > 0
              ? schools[0].id
              : null;
        }

        let membership = null;

        if (
          activeSchool &&
          !isSystemAdmin
        ) {
          membership =
            memberships.find(
              (item) =>
                item.schoolId ===
                activeSchool,
            ) || null;
        }

        this.session.firebaseUser = firebaseUser;
        this.session.profile = profile;
        this.session.schools = schools;
        this.session.activeSchool = activeSchool;
        this.session.membership = membership;
        this.startSchoolListener();
        this.session.initialized = true;

      } catch (error) {
        console.error(
          "Unable to initialize session:",
          error,
        );

        this.session.firebaseUser =
          firebaseUser;

        this.session.profile = null;
        this.session.schools = [];
        this.session.activeSchool = null;
        this.session.membership = null;
        this.session.initialized = true;        
      }
    },

    async onLoginSuccess() {
    },

    changePage(page) {
      const alwaysAllowedPages = [
        "dashboard",
        "settings",
        "profile",
      ];

      let canAccessPage =
        alwaysAllowedPages.includes(page);

      if (page === "students") {
        canAccessPage = this.canAccessStudents;
      }

      if (page === "classes") {
        canAccessPage = this.canAccessClasses;
      }

      if (
        [
          "courses",
          "buildings",
          "rooms",
          "reservations",
        ].includes(page)
      ) {
        canAccessPage =
          this.canManageSchoolStructure;
      }

      if (page === "admin") {
        canAccessPage = this.canAccessAdmin;
      }

      if (!canAccessPage) {
        this.selectedClassId = "";
        this.currentPage = "dashboard";
        return;
      }

      this.selectedClassId = "";
      this.currentPage = page;
    },

    openClassWorkspace(classId) {
      if (!this.canAccessClasses) {
        return;
      }

      this.selectedClassId = classId;
      this.currentPage = "class-workspace";
    },

    closeClassWorkspace() {
      this.selectedClassId = "";
      this.currentPage = "classes";
    },

    async handleSchoolChange(schoolId) {
      if (
        !schoolId ||
        schoolId === this.session.activeSchool
      ) {
        return;
      }

      const schoolExists =
        this.session.schools.some(
          (school) =>
            school.id === schoolId,
        );

      if (!schoolExists) {
        return;
      }

      const previousSchool =
        this.session.activeSchool;

      const previousMembership =
        this.session.membership;

      try {
        const membership =
          await getSchoolMembership(
            schoolId,
            this.session.firebaseUser.uid,
          );

        if (
          !this.isSystemAdmin &&
          (
            !membership ||
            membership.active === false
          )
        ) {
          return;
        }

        await updateActiveSchool(
          this.session.firebaseUser.uid,
          schoolId,
        );

        this.session.activeSchool =
          schoolId;

        this.session.membership =
          this.isSystemAdmin
            ? null
            : membership;
        this.session.profile = {
          ...this.session.profile,
          activeSchool: schoolId,
        };

        this.selectedClassId = "";
        this.currentPage = "dashboard";
      } catch (error) {
        console.error(
          "Unable to change school:",
          error,
        );

        this.session.activeSchool =
          previousSchool;

        this.session.membership =
          previousMembership;
      }
    },

    openProfile() {
      this.selectedClassId = "";
      this.currentPage = "profile";
    },

    handleProfileUpdated(updatedProfile) {
      this.session.profile = {
        ...this.session.profile,
        ...updatedProfile,
      };
    },

    async handleSignOut() {
      try {

        if (this.schoolUnsubscribe) {
          this.schoolUnsubscribe();
          this.schoolUnsubscribe = null;
        }
        await signOut(auth);

        this.selectedClassId = "";
        this.currentPage = "dashboard";

        this.session = {
          firebaseUser: null,
          profile: null,
          schools: [],
          activeSchool: null,
          membership: null,
          initialized: false,
        };
      } catch (error) {
        console.error("Unable to sign out:", error);
      }
    },

    startSchoolListener() {
      if (this.schoolUnsubscribe) {
        this.schoolUnsubscribe();
        this.schoolUnsubscribe = null;
      }

      if (!this.isSystemAdmin) {
        return;
      }

      this.schoolUnsubscribe =
        watchSchools(
          (items) => {
            const activeSchools =
              items.filter(
                (school) =>
                  school.active !== false,
              );

            this.session.schools =
              activeSchools;

            const activeSchoolStillExists =
              activeSchools.some(
                (school) =>
                  school.id ===
                  this.session.activeSchool,
              );

            if (!activeSchoolStillExists) {
              this.session.activeSchool =
                activeSchools.length > 0
                  ? activeSchools[0].id
                  : null;
            }
          },

          (error) => {
            console.error(
              "Unable to watch schools:",
              error,
            );
          },
        );
    },
  },
};
</script>

<style>
body {
  margin: 0;
  font-family: Arial, sans-serif;
}

.layout {
  display: flex;
}

main {
  flex: 1;
  min-width: 0;
}

.loading-screen {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
}

.inactive-account-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  box-sizing: border-box;
  background: #f5f5f5;
}

.inactive-account-card {
  width: 100%;
  max-width: 520px;
  padding: 32px;
  box-sizing: border-box;
  background: white;
  border: 1px solid #ddd;
  border-radius: 12px;
  text-align: center;
}

.inactive-account-card h1 {
  margin-top: 0;
}

.inactive-account-card button {
  margin-top: 16px;
  padding: 10px 18px;
  cursor: pointer;
}
</style>